import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, Link } from 'react-router-dom';  // Importando Link
import './ProjetoList.css'; // Importe o CSS para aplicar os estilos

const ProjetoList = () => {
  const [projetos, setProjetos] = useState([]);  // Lista de projetos
  const [loading, setLoading] = useState(true);  // Carregamento
  const [novoProjeto, setNovoProjeto] = useState({ nome: '', descricao: '' });  // Dados do novo projeto
  const { clienteId } = useParams(); // Pegando o clienteId da URL

  useEffect(() => {
    const fetchProjetos = async () => {
      try {
        const response = await axios.get(`http://localhost:8080/clientes/${clienteId}/projetos`);
        setProjetos(response.data);
      } catch (err) {
        console.error("Erro ao carregar projetos", err);
      } finally {
        setLoading(false);
      }
    };

    fetchProjetos();
  }, [clienteId]);

  // Função para lidar com a criação de um novo projeto
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Verificar se os campos do formulário estão preenchidos
    if (!novoProjeto.nome || !novoProjeto.descricao) {
      alert('Por favor, preencha todos os campos!');
      return;
    }

    try {
      const response = await axios.post(
        `http://localhost:8080/clientes/${clienteId}/projetos`,
        novoProjeto
      );

      // Atualizar a lista de projetos com o novo projeto criado
      setProjetos([...projetos, response.data]);

      // Limpar o formulário
      setNovoProjeto({ nome: '', descricao: '' });

    } catch (err) {
      console.error("Erro ao criar projeto", err);
      alert('Erro ao criar projeto!');
    }
  };

  return (
    <div className="projeto-list">
      <h3>Projetos do Cliente</h3>

      {/* Formulário para criar novo projeto */}
      <form onSubmit={handleSubmit} className="form-criar-projeto">
        <h4>Criar Novo Projeto</h4>
        <input
          type="text"
          value={novoProjeto.nome}
          onChange={(e) => setNovoProjeto({ ...novoProjeto, nome: e.target.value })}
          placeholder="Nome do Projeto"
          required
        />
        <textarea
          value={novoProjeto.descricao}
          onChange={(e) => setNovoProjeto({ ...novoProjeto, descricao: e.target.value })}
          placeholder="Descrição do Projeto"
          required
        />
        <button type="submit">Criar Projeto</button>
      </form>

      {loading ? (
        <p>Carregando...</p>
      ) : (
        <div className="projetos-container">
          {projetos.length === 0 ? (
            <p>Não há projetos para este cliente.</p>
          ) : (
            projetos.map((projeto) => (
              <div className="projeto-card" key={projeto.id}>
                <h4>{projeto.nome}</h4>
                <p>{projeto.descricao}</p>
                <Link to={`/clientes/${clienteId}/projetos/${projeto.id}/atividades`} className="detalhes-link">
                  Ver Detalhes
                </Link>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default ProjetoList;
